"""Assert that a pyproject.toml generated by the watcher has a dev group.

Usage: python3 check_manifest.py GROUP
The managers pin versions, so entries are compared by distribution name.
"""

import re
import sys
import tomllib

group = sys.argv[1]
with open("pyproject.toml", "rb") as handle:
    groups = tomllib.load(handle).get("dependency-groups", {})
print("dependency groups:", groups)

names = [
    re.split(r"[<>=!~;@\[]", requirement)[0].lower().replace("_", "-")
    for requirement in groups.get(group, [])
]
if "jupyterlab" not in names:
    sys.exit(f"jupyterlab is missing from the {group} group: {names}")
